<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue';
import EditorChoice from './EditorChoice.vue';
import {playbackResolverApi} from '@/services/api';
import type {PlaybackResolverConfig,PlaybackResolverSettings,PlaybackResolverResult,PlaybackResolverSource} from '@/services/api';
import type {Platform} from '@/domain/types';
const emit=defineEmits<{(e:'dirty',value:boolean):void;(e:'published',value:PlaybackResolverConfig):void}>();
const settings=ref<PlaybackResolverSettings|null>(null),draft=ref<PlaybackResolverConfig>({enabled:false,directFirst:true,timeoutSeconds:5,totalSeconds:15,maxAttempts:3,sources:[]});
const loading=ref(false),busy=ref(false),testing=ref(false),error=ref(''),message=ref(''),testURL=ref(''),testPlatform=ref<Platform>('mobile'),result=ref<PlaybackResolverResult|null>(null);
const switchValue=(event:Event)=>!!(event as Event & {detail:{value:boolean}}).detail.value;
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
const platforms:{id:Platform;label:string}[]=[{id:'mobile',label:'手机'},{id:'tablet',label:'平板'},{id:'tv',label:'电视'},{id:'web',label:'电脑'}];
const dirty=computed(()=>!!settings.value&&JSON.stringify(draft.value)!==JSON.stringify(settings.value.draft));
const unpublished=computed(()=>!!settings.value&&JSON.stringify(draft.value)!==JSON.stringify(settings.value.published));
const disabled=computed(()=>busy.value||testing.value||loading.value);
watch(dirty,value=>emit('dirty',value),{immediate:true});watch(draft,()=>{result.value=null;},{deep:true});
function receive(v:PlaybackResolverSettings){settings.value=v;draft.value=clone(v.draft);emit('published',clone(v.published));}
async function load(){loading.value=true;error.value='';try{receive(await playbackResolverApi.get());}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function save(){if(!settings.value||!validateHeaders())return;busy.value=true;error.value='';try{receive(await playbackResolverApi.save(settings.value.revision,draft.value));message.value='草稿已保存，发布后四端播放请求才会使用新配置。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function publish(){if(!settings.value||!validateHeaders())return;busy.value=true;error.value='';try{if(dirty.value)receive(await playbackResolverApi.save(settings.value.revision,draft.value));receive(await playbackResolverApi.publish(settings.value.revision));message.value='已发布至四端统一播放接口。';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function reload(){if(!dirty.value){void load();return;}uni.showModal({title:'重新加载配置',content:'当前有未保存的解析设置，重新加载会放弃这些修改。',success:r=>{if(r.confirm)void load();}});}
function add(){if(draft.value.sources.length>=32)return;draft.value.sources.push({id:'resolver-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),name:'',kind:'json',endpoint:'',urlField:'url',enabled:true,platforms:['mobile','tablet','tv','web']});}
function move(index:number,offset:number){const other=index+offset;if(other<0||other>=draft.value.sources.length)return;const rows=draft.value.sources;[rows[index],rows[other]]=[rows[other],rows[index]];}
function remove(index:number){uni.showModal({title:'移除解析来源',content:'从当前草稿移除此来源，发布后生效。',success:r=>{if(r.confirm)draft.value.sources.splice(index,1);}});}
function togglePlatform(source:PlaybackResolverSource,id:Platform){source.platforms=source.platforms.includes(id)?source.platforms.filter(p=>p!==id):[...source.platforms,id];}
async function test(){if(!validateHeaders())return;testing.value=true;error.value='';result.value=null;try{result.value=await playbackResolverApi.test(clone(draft.value),testURL.value.trim(),testPlatform.value);}catch(e){error.value=(e as Error).message;}finally{testing.value=false;}}
const allowedHeaders=['Accept','Accept-Language','Referer','Origin','X-Requested-With'];
function headerOptions(source:PlaybackResolverSource,current:string){return allowedHeaders.filter(name=>name===current||!Object.prototype.hasOwnProperty.call(source.headers||{},name)).map(name=>({id:name,label:name}));}
function addHeader(source:PlaybackResolverSource){const name=allowedHeaders.find(name=>!Object.prototype.hasOwnProperty.call(source.headers||{},name));if(name)source.headers={...source.headers,[name]:''};}
function renameHeader(source:PlaybackResolverSource,oldName:string,name:string){if(name===oldName||!allowedHeaders.includes(name)||Object.prototype.hasOwnProperty.call(source.headers||{},name))return;const headers={...source.headers};const value=headers[oldName]||'';delete headers[oldName];source.headers={...headers,[name]:value};}
function setHeader(source:PlaybackResolverSource,name:string,event:any){source.headers={...source.headers,[name]:String(event.detail?.value??'')};}
function removeHeader(source:PlaybackResolverSource,name:string){const headers={...source.headers};delete headers[name];source.headers=headers;}
function validateHeaders(){for(const [index,source] of draft.value.sources.entries()){if((source.userAgent||'').length>512||/[\r\n\0]/.test(source.userAgent||'')){error.value='来源 '+(index+1)+' 的 User-Agent 不能超过 512 字，且不能包含换行。';return false;}for(const [name,value] of Object.entries(source.headers||{})){if(!allowedHeaders.includes(name)||value.length>2048||/[\r\n\0]/.test(value)){error.value='来源 '+(index+1)+' 的请求头不符合格式，请使用列表中的请求头且不要输入换行。';return false;}}}return true;}
onMounted(load);
onBeforeUnmount(()=>emit('dirty',false));
</script>
<template>
<view class="resolver-center">
 <view class="heading"><view><text class="eyebrow">PLAYBACK RESOLVERS</text><text class="title">解析调度</text><text class="muted">四端共用播放规则 · 多来源按顺序尝试 · 失败自动切换</text></view><view class="actions"><button :disabled="disabled" @click="reload">重新加载</button><button :disabled="disabled||!settings||!dirty" @click="save">{{busy?'处理中…':'保存草稿'}}</button><button class="primary" :disabled="disabled||!settings||(!unpublished&&!dirty&&settings.publishedVersion>0)" @click="publish">发布配置</button></view></view>
 <view v-if="error" class="feedback failure" role="alert">{{error}}</view><view v-if="message" class="feedback" role="status">{{message}}</view>
 <view v-if="loading" class="empty">正在读取解析配置…</view>
 <template v-else-if="settings">
 <view class="summary"><view><text>配置状态</text><strong>{{draft.enabled?'已开启':'未开启'}}</strong></view><view><text>已启用来源</text><strong>{{draft.sources.filter(s=>s.enabled).length}} / {{draft.sources.length}}</strong></view><view><text>已发布版本</text><strong>{{settings.publishedVersion?'v'+settings.publishedVersion:'尚未发布'}}</strong></view><view><text>草稿状态</text><strong>{{dirty?'未保存':unpublished?'待发布':'已同步'}}</strong></view></view>

 <view class="panel"><view class="section-heading"><view><text class="section-title">调度策略</text><text class="muted">解析结果交给客户端播放；全部失败或达到总时限后停止。</text></view><switch :checked="draft.enabled" :disabled="disabled" @change="draft.enabled=switchValue($event)" aria-label="启用轮询解析"/></view>
 <view class="direct-option"><view><text>视频直链优先</text><text class="muted">MP4、M3U8 等已识别直链直接交给客户端；加载失败可排除此来源再请求解析。</text></view><switch :checked="draft.directFirst" :disabled="disabled" @change="draft.directFirst=switchValue($event)" aria-label="视频直链优先"/></view>
 <view class="strategy-grid"><label>单个来源超时（秒）<input v-model.number="draft.timeoutSeconds" type="number" :disabled="disabled" min="1" max="10"/></label><label>整体解析时限（秒）<input v-model.number="draft.totalSeconds" type="number" :disabled="disabled" min="1" max="20"/></label><label>最多尝试来源数<input v-model.number="draft.maxAttempts" type="number" :disabled="disabled" min="1" max="10"/></label></view></view>
 <view class="panel"><view class="section-heading"><view><text class="section-title">真实解析测试</text><text class="muted">使用当前草稿发起实际请求，不修改已发布配置。取得地址不等于真机播放成功。</text></view></view>
 <view class="test-grid"><label>影片来源地址<input v-model="testURL" :disabled="disabled" :maxlength="8192" placeholder="输入实际要解析的 HTTP(S) 地址"/></label><label>测试客户端<EditorChoice v-model="testPlatform" :options="platforms" :disabled="disabled"/></label><button class="primary" :disabled="disabled||!testURL.trim()" @click="test">{{testing?'正在逐个尝试…':'开始测试'}}</button></view>
 <view v-if="result" class="test-result" :class="{'failed-result':!result.ok}"><text class="section-title">{{result.ok?'已取得资源地址':'解析未成功'}}</text><text>{{result.message}}</text><text v-if="result.url" class="result-url" selectable>{{result.url}}</text><view v-for="(attempt,index) in result.attempts" :key="attempt.id" class="attempt"><text>{{index+1}}. {{attempt.name}}</text><text>{{attempt.ok?'成功':'失败'}} · {{attempt.elapsedMs}} ms</text><text>{{attempt.message}}</text></view><text v-if="!result.attempts.length" class="muted">{{result.sourceId==='direct'?'当前资源走直连，未调用解析服务。':'没有符合范围且可尝试的来源。'}}</text></view>
 </view>
 <view class="panel"><view class="section-heading"><view><text class="section-title">解析来源</text><text class="muted">从上往下尝试，支持 JSON 与 HTTP 跳转解析。每个来源可指定适用客户端。</text></view><button class="add" :disabled="disabled||draft.sources.length>=32" @click="add">＋ 添加解析来源</button></view>
 <view v-if="!draft.sources.length" class="empty"><text class="empty-title">尚未添加解析来源</text><text>添加你实际使用的解析接口，保存并发布后生效。</text></view>
 <view v-for="(source,index) in draft.sources" :key="source.id" class="source-card">
  <view class="source-heading"><view class="source-title"><text class="order">{{index+1}}</text><text>{{source.name||'未命名解析来源'}}</text><text class="pill">{{source.kind==='json'?'JSON':'HTTP 跳转'}}</text></view><view class="actions"><switch :checked="source.enabled" :disabled="disabled" @change="source.enabled=switchValue($event)" :aria-label="'启用来源 '+(index+1)"/><button :disabled="disabled||index===0" @click="move(index,-1)" :aria-label="'上移来源 '+(index+1)">上移</button><button :disabled="disabled||index===draft.sources.length-1" @click="move(index,1)" :aria-label="'下移来源 '+(index+1)">下移</button><button class="danger" :disabled="disabled" @click="remove(index)">移除</button></view></view>
  <view class="source-grid"><label>来源名称<input v-model="source.name" :disabled="disabled" maxlength="60" placeholder="填写解析服务名称"/></label><label>解析类型<EditorChoice v-model="source.kind" :disabled="disabled" :options="[{id:'json',label:'JSON 接口'},{id:'redirect',label:'HTTP 跳转'}]"/></label></view>
  <label>解析接口地址<input v-model="source.endpoint" :disabled="disabled" :maxlength="8192" placeholder="https://你的解析服务/api?url={url}"/></label><text class="muted field-help">用 {url} 表示影片来源地址，系统会自动进行 URL 编码。接口密钥仅保存在运营端，不发送给 APP。</text>
  <label v-if="source.kind==='json'">JSON 视频地址字段<input v-model="source.urlField" :disabled="disabled" maxlength="128" placeholder="url 或 data.url"/></label>
  <view class="request-options"><label>User-Agent（可选）<input v-model="source.userAgent" :disabled="disabled" maxlength="512" placeholder="留空使用默认请求标识"/></label><view class="header-heading"><text>附加请求头</text><button :disabled="disabled||Object.keys(source.headers||{}).length>=allowedHeaders.length" @click="addHeader(source)">＋ 添加请求头</button></view><view v-for="(value,name) in source.headers" :key="name" class="request-header"><EditorChoice :model-value="name" :options="headerOptions(source,name)" :disabled="disabled" @update:model-value="renameHeader(source,name,$event)"/><input :value="value" :disabled="disabled" maxlength="2048" :placeholder="name+' 的值'" :aria-label="name+' 的值'" @input="setHeader(source,name,$event)"/><button class="danger" :disabled="disabled" @click="removeHeader(source,name)">删除</button></view><text class="muted">请求头随解析请求发送，仅保存在服务端。</text></view>
  <view class="platform-row"><text>适用客户端</text><button v-for="p in platforms" :key="p.id" :class="{chosen:source.platforms.includes(p.id)}" :aria-pressed="source.platforms.includes(p.id)" :disabled="disabled" @click="togglePlatform(source,p.id)">{{p.label}}</button></view>
 </view></view>
 <view class="contract-note"><text>统一调用</text><text>APP 继续调用各端 playback 接口；服务端在原有 CMS 播放授权之后执行已发布解析规则。解析失败自动切换下一来源。客户端加载失败续试需提交 excludeSourceIds，具体字段见播放器接口文档。</text><text>最后发布：{{settings.publishedAt?new Date(settings.publishedAt).toLocaleString():'尚未发布'}} · 草稿修订 {{settings.revision}}</text></view>
 </template>
</view>
</template>
<style scoped>
.resolver-center{max-width:1500px;padding:30px;margin:0 auto;display:flex;flex-direction:column;gap:22px;color:inherit}.heading,.section-heading,.source-heading{display:flex;align-items:center;justify-content:space-between;gap:20px}.heading>view:first-child,.section-heading>view:first-child{display:flex;flex-direction:column;gap:9px}.eyebrow{font-size:11px;letter-spacing:2px;opacity:.5}.title{font-size:27px;font-weight:650}.muted{font-size:12px;opacity:.63;line-height:1.8}.actions{display:flex;align-items:center;gap:10px;flex-shrink:0}button{margin:0;font-size:12px;line-height:2.8;padding:0 16px;background:transparent;color:inherit;border:1px solid #80808035;border-radius:9px}button::after{border:0}button[disabled]{opacity:.4}.primary,.add{background:#e5eddf;color:#35533a;border-color:#d5e2cb}.primary{font-weight:600}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.summary>view{border:1px solid #80808025;border-radius:13px;padding:20px;display:flex;flex-direction:column;gap:12px;background:#80808006}.summary text{font-size:12px;opacity:.6}.summary strong{font-size:19px;font-weight:600}.panel{padding:24px;border:1px solid #80808025;border-radius:15px;background:#80808005}.section-title{font-size:17px;font-weight:600;display:block}.direct-option{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #80808020;border-bottom:1px solid #80808020;padding:20px 0;margin:20px 0;gap:20px}.direct-option>view{display:flex;flex-direction:column;gap:6px;font-size:14px}.strategy-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}label{display:flex;flex-direction:column;gap:10px;font-size:12px}input{height:42px;padding:0 12px;border:1px solid #80808035;border-radius:8px;background:#80808007;color:inherit;box-sizing:border-box;font-size:13px;min-width:0}.source-card{padding:22px;border:1px solid #80808025;border-radius:12px;margin-top:18px;display:flex;flex-direction:column;gap:16px;background:#80808003}.source-title{display:flex;align-items:center;gap:10px;font-size:14px;font-weight:600}.order{background:#b1c5a528;border-radius:7px;padding:5px 10px}.pill{font-size:10px;font-weight:400;border:1px solid #80808035;padding:3px 8px;border-radius:20px;opacity:.75}.source-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.field-help{margin-top:-9px;overflow-wrap:anywhere}.platform-row{display:flex;gap:10px;align-items:center;font-size:12px}.platform-row>text{margin-right:10px}.chosen{background:#b1c5a52b;border-color:#86a677}.danger{color:#c46a6a}.empty{display:flex;flex-direction:column;align-items:center;gap:12px;padding:44px 20px;color:inherit;opacity:.65;font-size:13px}.empty-title{font-size:16px;font-weight:600}.test-grid{display:grid;grid-template-columns:minmax(200px,1fr) 210px auto;align-items:end;gap:16px;margin-top:22px}.test-result{display:flex;flex-direction:column;gap:15px;padding:22px;margin-top:22px;border:1px solid #8ca58260;border-radius:10px;font-size:13px;background:#b1c5a50b}.failed-result{border-color:#ca8b6f70}.result-url{white-space:pre-wrap;overflow-wrap:anywhere;padding:12px;border-radius:7px;background:#80808014;font-family:monospace}.attempt{display:grid;grid-template-columns:1fr auto;gap:9px;padding-top:14px;border-top:1px solid #80808025}.attempt>text:last-child{grid-column:1/-1;opacity:.6;font-size:12px}.feedback{border-radius:9px;padding:14px 18px;background:#a6bd8e25;font-size:13px}.failure{background:#d7777720;color:#ca6666}.contract-note{display:flex;flex-direction:column;gap:8px;font-size:12px;opacity:.65;line-height:1.9}.contract-note>text:first-child{font-weight:600}@media(max-width:1150px){.heading,.source-heading{align-items:flex-start;flex-direction:column}.resolver-center{padding:20px}.test-grid{grid-template-columns:1fr}.summary{grid-template-columns:repeat(2,1fr)}}
.request-options{display:flex;flex-direction:column;gap:12px;border-top:1px solid #80808025;padding-top:16px}.header-heading{display:flex;align-items:center;justify-content:space-between;font-size:12px}.request-header{display:grid;grid-template-columns:210px minmax(100px,1fr) auto;gap:12px;align-items:center}@media(max-width:700px){.request-header{grid-template-columns:1fr auto}.request-header>input{grid-column:1/-1;grid-row:2}.request-header>button{grid-column:2;grid-row:1}}
</style>
